//! Fixture parity tests for the Higgs Audio tokenizer port.
//!
//! Fixtures live in `testdata/higgs_audio/`, regenerated by
//! `tools/gen_higgs_fixtures.py` against the pinned mlx-audio commit
//! (tiny geometry: the reference hardcodes channel ladders and the
//! 1024/256 dims as class/constructor constants, so the generator
//! mirrors the `__init__` bodies at shrunk dims with identical weight
//! keys). Gates: acoustic encode, RVQ encode/decode, full token
//! decode. A real checkpoint can be pointed at via
//! TURBOSPARK_HIGGS_AUDIO_MODEL and is skipped when absent. Tests
//! never download.

use std::path::{Path, PathBuf};

use super::{HiggsAudioConfig, HiggsAudioTokenizer};
use turbospark_model_io::safetensors::SafetensorsFile;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/higgs_audio")
        .join(name)
}

fn read_json(name: &str) -> serde_json::Value {
    let text = std::fs::read_to_string(testdata(name)).expect(name);
    serde_json::from_str(&text).expect(name)
}

fn read_npy(name: &str) -> (Vec<usize>, Vec<f32>) {
    let bytes = std::fs::read(testdata(name)).expect(name);
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    assert!(header.contains("<f4"), "{name} must be f32");
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let data = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (shape, data)
}

/// Codes arrive as int32 (`<i4`), rows = frames, columns = books
/// (the reference stacks codes on the last axis).
fn read_codes(name: &str) -> Vec<Vec<i32>> {
    let bytes = std::fs::read(testdata(name)).expect(name);
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    assert!(header.contains("<i4"), "{name} must be int32");
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    assert_eq!(shape.len(), 2, "{name} must be [T, books]");
    let (t, books) = (shape[0], shape[1]);
    let data: Vec<i32> = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (0..books)
        .map(|b| (0..t).map(|ti| data[ti * books + b]).collect())
        .collect()
}

fn rel_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(a.len(), b.len());
    let max = b.iter().fold(0.0f32, |acc, v| acc.max(v.abs()));
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
        / max
}

fn load_tiny() -> HiggsAudioTokenizer {
    let config = read_json("tiny_config.json");
    let config = HiggsAudioConfig::from_json(&config).expect("config");
    let file = SafetensorsFile::open(&testdata("tiny_weights.safetensors")).expect("weights");
    HiggsAudioTokenizer::load(config, &file).expect("load")
}

#[test]
fn config_defaults_match_reference() {
    let config = HiggsAudioConfig::from_json(&serde_json::json!({})).unwrap();
    assert_eq!(config.sample_rate, 24_000);
    assert_eq!(config.codebook_size, 1024);
    assert_eq!(config.codebook_dim, 64);
    assert_eq!(config.downsample_factor, 320);
    assert_eq!(config.dac_num_codebooks, 8);
    assert_eq!(config.dac_encoder_ratios, vec![8, 5, 4, 2, 3]);
    assert_eq!(config.dac_encoder_hidden, 64);
    assert_eq!(config.dac_decoder_hidden, 1024);
    assert_eq!(config.quantizer_latent_dim, 1024);
    assert_eq!(config.decoder_input_dim, 256);
    assert_eq!(config.acoustic_hop(), 960);
    assert_eq!(
        config.encoder_channels(),
        vec![64, 128, 256, 512, 1024, 2048]
    );
}

#[test]
fn acoustic_encoder_matches_reference() {
    let model = load_tiny();
    let traces = read_json("traces.json");
    for tag in ["a", "b"] {
        let (_, wave) = read_npy(&format!("{tag}_wave.npy"));
        let (feat_shape, golden) = read_npy(&format!("{tag}_acoustic.npy"));
        let rows = model.encode_acoustic(&wave).unwrap();
        assert_eq!(
            feat_shape,
            vec![
                rows.len() / model.config.decoder_input_dim,
                model.config.decoder_input_dim
            ]
        );
        // The tiny random-weight stack amplifies features to ~6e10
        // (see the generator), where f32 accumulation-order noise is
        // around 1e-5 relative; 1e-4 is the honest gate at that scale.
        let rel = rel_diff(&rows, &golden);
        assert!(rel < 1e-4, "tag {tag} acoustic rel diff {rel}");
        assert_eq!(
            rows.len() / model.config.decoder_input_dim,
            wave.len() / model.config.acoustic_hop()
        );
        let _ = traces;
    }
}

#[test]
fn rvq_round_trip_matches_reference() {
    let model = load_tiny();
    let traces = read_json("traces.json");
    let (z_shape, z) = read_npy("z_rows.npy");
    let frames = z_shape[0];
    let codes = model.rvq_encode(&z, frames).unwrap();
    let golden_codes = read_codes("codes.npy");
    assert_eq!(codes.len(), golden_codes.len());
    for (b, (mine, golden)) in codes.iter().zip(&golden_codes).enumerate() {
        assert_eq!(mine, golden, "book {b}");
    }
    let margin = traces["rvq_min_margin"].as_f64().unwrap();
    assert!(margin > 1e-4, "rvq margin {margin}");

    let (_, golden_recon) = read_npy("z_recon.npy");
    let recon = model.rvq_decode_rows(&codes).unwrap();
    let rel = rel_diff(&recon, &golden_recon);
    assert!(rel < 1e-5, "rvq recon rel diff {rel}");
}

#[test]
fn token_decode_matches_reference() {
    let model = load_tiny();
    let (_, golden) = read_npy("decoded.npy");
    let codes = read_codes("codes.npy");
    let wav = model.decode_tokens(&codes).unwrap();
    assert_eq!(wav.len(), golden.len());
    // Same amplification story as the acoustic gate: the decoded
    // waveform peaks near 2e4 and f32 order noise lands around 3e-5.
    let rel = rel_diff(&wav, &golden);
    assert!(rel < 1e-4, "decode rel diff {rel}");
    assert_eq!(wav.len(), codes[0].len() * model.config.acoustic_hop());
}

#[test]
fn decode_validates_codes() {
    let model = load_tiny();
    let too_many = vec![vec![0i32; 2]; model.config.dac_num_codebooks + 1];
    assert!(model.decode_tokens(&too_many).is_err());
    let bad = vec![vec![model.config.codebook_size as i32; 2]];
    assert!(model.decode_tokens(&bad).is_err());
}

/// Real-checkpoint gate; opt-in via TURBOSPARK_HIGGS_AUDIO_MODEL
/// pointing at a directory with config.json + model.safetensors.
/// Skips when unset.
#[test]
fn real_checkpoint_gate() {
    let Ok(dir) = std::env::var("TURBOSPARK_HIGGS_AUDIO_MODEL") else {
        eprintln!("skipping: TURBOSPARK_HIGGS_AUDIO_MODEL not set");
        return;
    };
    let model = HiggsAudioTokenizer::open(Path::new(&dir)).unwrap();
    let codes: Vec<Vec<i32>> = (0..model.config.dac_num_codebooks)
        .map(|b| {
            (0..4)
                .map(|t| ((b + t) % model.config.codebook_size) as i32)
                .collect()
        })
        .collect();
    let wav = model.decode_tokens(&codes).unwrap();
    assert_eq!(wav.len(), 4 * model.config.acoustic_hop());
    assert!(wav.iter().all(|v| v.is_finite()));
}

// The released-format encode fixture: PyTorch conv layouts, the
// Wav2Vec2 semantic tower, `encoder_semantic`, and the fusion, at
// shrunk dims. Regenerated by `tools/gen_higgs_encode_fixture.py`
// against the pinned mlx-audio commit.

fn encode_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("testdata/higgs_audio_encode")
}

fn read_encode_json(name: &str) -> serde_json::Value {
    let text = std::fs::read_to_string(encode_dir().join(name)).expect(name);
    serde_json::from_str(&text).expect(name)
}

fn read_encode_npy(name: &str) -> (Vec<usize>, Vec<f32>) {
    let bytes = std::fs::read(encode_dir().join(name)).expect(name);
    assert_eq!(&bytes[..6], b"\x93NUMPY");
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    assert!(header.contains("<f4"), "{name} must be f32");
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let data = bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    (shape, data)
}

/// Reads a frames-major int32 npy `[T, books]`.
fn read_encode_codes(name: &str) -> Vec<Vec<i32>> {
    let bytes = std::fs::read(encode_dir().join(name)).expect(name);
    let header_len = u16::from_le_bytes([bytes[8], bytes[9]]) as usize;
    let header = std::str::from_utf8(&bytes[10..10 + header_len]).unwrap();
    assert!(header.contains("<i4"), "{name} must be int32");
    let start = header.find('(').unwrap() + 1;
    let end = header[start..].find(')').unwrap() + start;
    let shape: Vec<usize> = header[start..end]
        .split(',')
        .filter_map(|p| p.trim().parse::<usize>().ok())
        .collect();
    let (t, books) = (shape[0], shape[1]);
    bytes[10 + header_len..]
        .chunks_exact(4)
        .map(|c| i32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect::<Vec<_>>()
        .chunks(books)
        .map(|row| row.to_vec())
        .take(t)
        .collect()
}

#[test]
fn released_format_config_parses_and_encode_refuses_without_the_semantic_path() {
    let model = load_tiny();
    assert!(model.config.semantic_model_config.is_none());
    // The decode-only tiny fixture has no semantic path: encoding a
    // reference must refuse, not return garbage.
    let error = model.encode_tokens(&[0.1f32; 960]).err().unwrap();
    assert!(error.to_string().contains("semantic encode path"));
}

#[test]
fn encode_fixture_pipeline_matches_the_reference() {
    let traces = read_encode_json("traces.json");
    let tokenizer =
        HiggsAudioTokenizer::open(&encode_dir()).expect("released-format fixture opens");
    // The released config nests the DAC geometry under
    // acoustic_model_config; the parser must have picked it up.
    assert_eq!(tokenizer.config.dac_encoder_ratios, vec![8, 5, 4, 2, 3]);
    assert_eq!(tokenizer.config.dac_encoder_hidden, 4);
    assert_eq!(tokenizer.config.dac_decoder_hidden, 32);
    assert_eq!(tokenizer.config.decoder_input_dim, 256);
    assert_eq!(tokenizer.config.quantizer_latent_dim, 272);
    assert_eq!(
        tokenizer.config.dac_num_codebooks,
        traces["books"].as_u64().unwrap() as usize
    );
    assert!(tokenizer.config.semantic_model_config.is_some());

    for tag in ["a", "b"] {
        let (wave_shape, wave) = read_encode_npy(&format!("{tag}_wave.npy"));
        let input_len = wave_shape[0];

        // The sinc resample (torchaudio sinc_interp_hann parity).
        let (_, golden_resampled) = read_encode_npy(&format!("{tag}_resampled.npy"));
        let resampled = super::sinc_resample(&wave, 24000, 16000);
        assert_eq!(
            resampled.len(),
            golden_resampled.len(),
            "{tag} resample length"
        );
        let rel = rel_diff(&resampled, &golden_resampled);
        assert!(rel < 1e-5, "{tag} sinc resample rel diff {rel}");

        // The tower hidden-state mean over the padded input.
        let file = SafetensorsFile::open(&encode_dir().join("model.safetensors")).unwrap();
        let tower = crate::stt::wav2vec::SemanticTower::load(
            &file,
            tokenizer.config.semantic_model_config.as_ref().unwrap(),
        )
        .unwrap();
        let pad = traces["hubert_pad"].as_u64().unwrap() as usize;
        let mut tower_input = vec![0.0f32; pad];
        tower_input.extend_from_slice(&resampled);
        tower_input.extend(std::iter::repeat_n(0.0f32, pad));
        let (mean, _final, steps) = tower.forward_hidden_mean(&tower_input).unwrap();
        assert_eq!(
            steps,
            traces[format!("{tag}_tower_steps").as_str()]
                .as_u64()
                .unwrap() as usize,
            "{tag} tower steps"
        );
        let (mean_shape, golden_mean) = read_encode_npy(&format!("{tag}_semantic_mean.npy"));
        assert_eq!(mean_shape[0] * mean_shape[1], mean.len());
        assert_eq!(steps, mean_shape[0], "{tag} mean rows");
        let rel = rel_diff(&mean, &golden_mean);
        assert!(rel < 2e-4, "{tag} tower mean rel diff {rel}");

        // The semantic encoder over the downsampled mean.
        let dsf = traces["dsf"].as_u64().unwrap() as usize;
        let kept = steps.div_ceil(dsf);
        let hidden = tower.config().hidden_size;
        let mut sliced = vec![0.0f32; kept * hidden];
        for t in 0..kept {
            let source = t * dsf;
            sliced[t * hidden..(t + 1) * hidden]
                .copy_from_slice(&mean[source * hidden..(source + 1) * hidden]);
        }
        let encoder = super::SemanticEncoder::load(
            &file,
            hidden,
            &tokenizer.config.strides,
            &tokenizer.config.block_dilations,
            &tokenizer.config.channel_ratios,
            tokenizer.config.kernel_size,
            tokenizer.config.unit_kernel_size,
        )
        .unwrap();
        let encoded = encoder.forward(&sliced, kept).unwrap();
        let (enc_shape, golden_encoded) = read_encode_npy(&format!("{tag}_semantic_encoded.npy"));
        assert_eq!(encoded.len(), golden_encoded.len(), "{tag} encoded length");
        assert_eq!(encoded.len(), enc_shape[0] * enc_shape[1]);
        let rel = rel_diff(&encoded, &golden_encoded);
        assert!(rel < 1e-4, "{tag} semantic encoder rel diff {rel}");

        // The full encode: codes must be exact.
        let codes = tokenizer.encode_tokens(&wave).expect("encode");
        let golden_codes = read_encode_codes(&format!("{tag}_codes.npy"));
        assert_eq!(codes.len(), golden_codes.len(), "{tag} code frames");
        assert_eq!(
            codes.len(),
            traces[format!("{tag}_frames").as_str()].as_u64().unwrap() as usize
        );
        for (t, (mine, golden)) in codes.iter().zip(&golden_codes).enumerate() {
            assert_eq!(mine, golden, "{tag} frame {t}");
        }
        let _ = input_len;
    }
}
